+	api_v1 "github.com/prometheus/prometheus/web/api/v1"
+)
+
+const reloadStatusFilename = "reload-status.json"
+
+// reloadStatusStore keeps the last transactional reload result in memory and,
+// after a reload attempt, on disk as well. A malformed status file is treated
+// as if no reload has happened yet.
+type reloadStatusStore struct {
+	mu       sync.RWMutex
+	path     string
+	status   api_v1.ReloadStatus
+}
+
+func newReloadStatusStore(dir string) *reloadStatusStore {
+	s := &reloadStatusStore{path: filepath.Join(dir, reloadStatusFilename)}
+	s.status = emptyReloadStatus()
+
+	b, err := os.ReadFile(s.path)
+	if err != nil {
+		return s
+	}
+	var status api_v1.ReloadStatus
+	if json.Unmarshal(b, &status) != nil {
+		return s
+	}
+	s.status = normalizeReloadStatus(status)
+	return s
+}
+
+func emptyReloadStatus() api_v1.ReloadStatus {
+	return api_v1.ReloadStatus{
+		AppliedReloaders:  []string{},
+		ErrorCategory:     "none",
+		ReloaderTimingsMS: map[string]float64{},
+	}
+}
+
+func normalizeReloadStatus(status api_v1.ReloadStatus) api_v1.ReloadStatus {
+	if status.AppliedReloaders == nil {
+		status.AppliedReloaders = []string{}
+	}
+	if status.ReloaderTimingsMS == nil {
+		status.ReloaderTimingsMS = map[string]float64{}
+	}
+	switch status.ErrorCategory {
+	case "none", "load_error", "apply_error", "rollback_error":
+	default:
+		status.ErrorCategory = "none"
+	}
+	return status
+}
+
+func (s *reloadStatusStore) Get() api_v1.ReloadStatus {
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+	status := s.status
+	status.AppliedReloaders = append([]string(nil), status.AppliedReloaders...)
+	status.ReloaderTimingsMS = make(map[string]float64, len(s.status.ReloaderTimingsMS))
+	for k, v := range s.status.ReloaderTimingsMS {
+		status.ReloaderTimingsMS[k] = v
+	}
+	return status
+}
+
+func (s *reloadStatusStore) Set(status api_v1.ReloadStatus) {
+	status = normalizeReloadStatus(status)
+	s.mu.Lock()
+	s.status = status
+	s.mu.Unlock()
+
+	// A persistence error must not turn a reload into a failed reload.
+	if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
+		return
+	}
+	b, err := json.Marshal(status)
+	if err != nil {
+		return
+	}
+	tmp, err := os.CreateTemp(filepath.Dir(s.path), ".reload-status-*")
+	if err != nil {
+		return
+	}
+	tmpName := tmp.Name()
+	defer os.Remove(tmpName)
+	if _, err := tmp.Write(b); err != nil || tmp.Close() != nil {
+		return
+	}
+	_ = os.Rename(tmpName, s.path)
+}
