+func reloadConfigTransaction(conf *config.Config, filename string, logger *slog.Logger, noStepSubqueryInterval *safePromQLNoStepSubqueryInterval, timingsLogger *slog.Logger, statusStore *reloadStatusStore, recordOutcome bool, rls ...reloader) error {
+	start := time.Now()
+	timings := map[string]float64{}
+	applied := []string{}
+	for _, rl := range rls {
+		rstart := time.Now()
+		err := rl.reloader(conf)
+		timings[rl.name] = float64(time.Since(rstart)) / float64(time.Millisecond)
+		if err != nil {
+			if recordOutcome {
+				status := api_v1.ReloadStatus{
+					LastReloadID:      time.Now().UTC().Format(time.RFC3339),
+					ErrorCategory:     "apply_error",
+					ErrorMessage:      err.Error(),
+					AppliedReloaders:  applied,
+					FailedReloader:    rl.name,
+					ReloaderTimingsMS: timings,
+				}
+				if len(applied) > 0 && transactionalLastGoodConfig != nil {
+					status.RollbackAttempted = true
+					rollbackErr := applyReloaders(transactionalLastGoodConfig, rls, timings)
+					status.RollbackSuccessful = rollbackErr == nil
+					if rollbackErr != nil {
+						status.ErrorCategory = "rollback_error"
+						status.ErrorMessage = fmt.Sprintf("apply failed in %s: %v; rollback failed: %v", rl.name, err, rollbackErr)
+					}
+				}
+				statusStore.Set(status)
+			}
+			return fmt.Errorf("failed to apply configuration in reloader %q: %w", rl.name, err)
+		}
+		applied = append(applied, rl.name)
+	}
+
+	transactionalLastGoodConfig = conf
+	updateGoGC(conf, logger)
+	noStepSubqueryInterval.Set(conf.GlobalConfig.EvaluationInterval)
+	timingsLogger.Info("Completed loading of configuration file", "filename", filename, "totalDuration", time.Since(start))
+	if recordOutcome {
+		statusStore.Set(api_v1.ReloadStatus{
+			LastReloadID:         time.Now().UTC().Format(time.RFC3339),
+			LastReloadSuccessful: true,
+			ErrorCategory:        "none",
+			AppliedReloaders:     applied,
+			ReloaderTimingsMS:    timings,
+		})
+	}
+	return nil
+}
+
+var transactionalLastGoodConfig *config.Config
+
+func applyReloaders(conf *config.Config, rls []reloader, timings map[string]float64) error {
+	for _, rl := range rls {
+		start := time.Now()
+		err := rl.reloader(conf)
+		timings[rl.name] += float64(time.Since(start)) / float64(time.Millisecond)
+		if err != nil {
+			return fmt.Errorf("%s: %w", rl.name, err)
+		}
+	}
+	return nil
+}
